xpath.script:
let zfmdChromeObserverStarted = false;
function zfmdNormalizeTitle() {
    const baseTitle = "兆方美迪项目管理系统";
    const current = document.title || "";
    const repeatedPrefix = new RegExp("^(" + baseTitle + "\\s*-\\s*)+", "g");
    const cleaned = current
        .replace(repeatedPrefix, "")
        .replace(/^Odoo\\s*-\\s*/i, "")
        .replace(/\\s*-\\s*Odoo$/i, "")
        .trim();
    const nextTitle = cleaned && cleaned !== baseTitle ? (baseTitle + " - " + cleaned) : baseTitle;
    if (document.title !== nextTitle) {
        document.title = nextTitle;
    }
}
function zfmdTrimChrome() {
    const systray = document.querySelector(".o_menu_systray");
    if (systray) {
        for (const item of systray.children) {
            if (!item.querySelector(".o_user_menu")) {
                item.style.display = "none";
            }
        }
    }
    for (const icon of document.querySelectorAll('.o_menu_systray i[aria-label="Activities"], .o_menu_systray i[aria-label="Messages"]')) {
        const dropdown = icon.closest(".dropdown");
        const item = icon.closest(".o_menu_systray_item");
        if (dropdown) {
            dropdown.style.display = "none";
        }
        if (item) {
            item.style.display = "none";
        }
    }
    for (const item of document.querySelectorAll("[data-menu]")) {
        if (item.dataset.menu !== "logout") {
            item.style.display = "none";
        }
    }
    for (const divider of document.querySelectorAll(".o_user_menu .dropdown-divider")) {
        divider.style.display = "none";
    }
    zfmdNormalizeTitle();
}
document.addEventListener("DOMContentLoaded", zfmdTrimChrome);
window.addEventListener("load", zfmdTrimChrome);
document.addEventListener("DOMContentLoaded", function () {
    if (!zfmdChromeObserverStarted) {
        const observer = new MutationObserver(function () {
            window.requestAnimationFrame(zfmdTrimChrome);
        });
        observer.observe(document.body, { childList: true, subtree: true });
        zfmdChromeObserverStarted = true;
    }
});
